import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.notification.Notification;
import com.vaadin.flow.component.notification.NotificationTester;
import com.vaadin.flow.component.textfield.EmailField;
import com.vaadin.flow.component.textfield.TextArea;
import com.vaadin.flow.component.textfield.TextField;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    @Test
    void headingAndFieldsPresent() {
        ContactView view = navigate(ContactView.class);
        H1 heading = $(H1.class).first();
        assertEquals("Contact", heading.getText());

        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();
        Button send = $(Button.class).withText("Send").single();

        assertEquals("", name.getValue());
        assertEquals("", email.getValue());
        assertEquals("", message.getValue());
        assertTrue(send.isEnabled());
    }

    @Test
    void sendingWithBlankNameMarksInvalidAndDoesNotNotify() {
        navigate(ContactView.class);
        TextField name = $(TextField.class).withLabel("Name").single();
        Button send = $(Button.class).withText("Send").single();

        test(send).click();

        assertTrue(name.isInvalid());
        assertFalse($(Notification.class).exists());
    }

    @Test
    void sendingWithNameSendsAndClearsFields() {
        navigate(ContactView.class);
        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();
        Button send = $(Button.class).withText("Send").single();

        test(name).setValue("Ada");
        test(email).setValue("ada@example.com");
        test(message).setValue("Hello there");

        test(send).click();

        Notification notification = $(Notification.class).single();
        NotificationTester<Notification> tester = test(notification);
        assertTrue(tester.getText().contains("Message sent"));

        assertEquals("", name.getValue());
        assertEquals("", email.getValue());
        assertEquals("", message.getValue());
        assertFalse(name.isInvalid());
    }
}
